import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {Repository} from '@github-ui/current-repository'
import type {Pull} from '../../../types/pull'
import type {PublicUser} from '../../../types/public-user'
import type {Session} from '../../../types/session'
import type {AgentMention} from '../../../types/agent-mention'
import type {HydratedAPITask} from '../../../types/api-task'
import {maybeNormalizeSession} from '../../../types/api-task'

class NotFoundError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'NotFoundError'
  }
}

export interface TaskPayload {
  taskId?: string
  pull?: Pull
  sessions: Session[]
  currentUser: PublicUser | undefined
  currentUserCanPush: boolean
  steeringEnabled: boolean
  useTokenBasedBilling?: boolean
  remoteControlPolicyEnabled: boolean
  logsPollingInterval?: number
  sessionsPollingInterval?: number
  agentMentions?: AgentMention[] | null
  task?: HydratedAPITask
  branchAliveChannel?: string
  initialAuthToken?: {token: string; expiration: string; ssoOrgIDs?: string[]}
}

export function useTaskPayload(repository: Repository, pullRequestNumber: number) {
  return useQuery<TaskPayload>({
    queryKey: ['pull-request-side-panel', 'task-payload', repository.ownerLogin, repository.name, pullRequestNumber],
    queryFn: async () => {
      const resp = await verifiedFetchJSON(
        `/${repository.ownerLogin}/${repository.name}/agents/pull/${pullRequestNumber}.json`,
      )
      if (resp.status === 404) {
        throw new NotFoundError('No agent sessions for this pull request.')
      }
      if (!resp.ok) {
        throw new Error(`Failed to fetch sessions: ${resp.statusText}`)
      }
      const sessionsData = await resp.json()

      // The backend response has structure: { meta: {...}, payload: {...} }
      const backendPayload = sessionsData.payload.repoTaskRoute
      return {
        pull: backendPayload.pull,
        sessions: (backendPayload.sessions || []).map(maybeNormalizeSession),
        currentUser: backendPayload.currentUser,
        currentUserCanPush: backendPayload.currentUserCanPush ?? false,
        steeringEnabled: backendPayload.steeringEnabled ?? false,
        useTokenBasedBilling: backendPayload.useTokenBasedBilling ?? false,
        remoteControlPolicyEnabled: backendPayload.remoteControlPolicyEnabled ?? false,
        agentMentions: backendPayload.agentMentions || [],
        branchAliveChannel: backendPayload.branchAliveChannel,
        taskId: backendPayload.taskId,
        task: backendPayload.task,
        initialAuthToken: backendPayload.initialAuthToken,
      } satisfies TaskPayload
    },
    staleTime: Infinity,
  })
}
